DELETE FROM students WHERE tenant_id = 'INST_PATNA_01';
DELETE FROM tests WHERE tenant_id = 'INST_PATNA_01';
DELETE FROM batches WHERE tenant_id = 'INST_PATNA_01';
DELETE FROM institutes WHERE id != 'INST_PATNA_01';

